{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Contact • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--muted:#6c6c6c;--accent:#6b8e6b;--card:#ffffff;--glass:rgba(255,255,255,0.6);--shadow: 0 6px 20px rgba(28,28,28,0.06);--radius:14px;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial}
    html,body{height:100%;margin:0;background:var(--bg);color:#111}
    body{display:flex;flex-direction:column}
    header{background:linear-gradient(180deg,rgba(107,142,107,0.06),transparent);backdrop-filter:blur(4px);padding:22px 28px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#a9cfa9);display:grid;place-items:center;color:#fff;font-weight:600}
    nav a{margin-left:14px;text-decoration:none;color:#334; font-weight:600}
    main{max-width:1100px;margin:28px auto;padding:28px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:22px}
    .card{background:var(--card);border-radius:var(--radius);box-shadow:var(--shadow);padding:20px}
    .hero{display:flex;gap:18px;align-items:flex-start}
    .hero h1{margin:0;font-size:20px}
    p.lead{color:var(--muted);margin:8px 0 0}
    form .row{display:flex;gap:10px;margin-bottom:10px}
    label{font-size:13px;color:var(--muted);display:block;margin-bottom:6px}
    input[type=text],input[type=email],textarea,select{width:100%;padding:10px;border-radius:10px;border:1px solid #e7e7e7;background:transparent}
    button.primary{background:var(--accent);color:#fff;border:0;padding:10px 14px;border-radius:10px;cursor:pointer}
    footer{padding:30px 28px;text-align:center;color:var(--muted);font-size:13px}

    /* Session planner & Blend builder styles */
    .widget h3{margin:0 0 10px}
    .summary{white-space:pre-wrap;background:linear-gradient(180deg,#fbfff9,#ffffff);padding:12px;border-radius:10px;border:1px dashed #e2efe2;color:#123}
    .controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .chip{background:#f3f7f3;padding:6px 10px;border-radius:999px;font-size:13px}

    /* responsive */
    @media (max-width:980px){.grid{grid-template-columns:1fr;}.brand nav{display:none}}
    /* subtle SVG pattern cover */
    .pattern-cover{position:fixed;inset:0;pointer-events:none;opacity:0.08;background-image:url('assets/img/pattern.svg');background-repeat:repeat;mix-blend-mode:multiply}
  </style>
</head>
<body>
  <div class="pattern-cover" aria-hidden></div>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Concoctions</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Meet</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <section class="card hero">
          <div style="flex:1">
            <h1>Reach out & begin a plant-guided exploration</h1>
            <p class="lead">Use this page to ask about sessions, events, or to co-create a blend. We run small series-style events and private consultations that may support rest, focus, and ritual.</p>
            <p style="margin-top:12px;color:var(--muted)"><strong>Phone:</strong> {{PHONE}} • <strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          </div>
          <div style="width:220px;text-align:right">
            <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </section>

        <section class="card" style="margin-top:18px">
          <h3>Session Planner — create a short plan for a single client/session</h3>
          <p style="color:var(--muted);margin-top:6px">Build a personalized plan and export a plaintext summary to copy into notes or a booking system.</p>

          <div style="margin-top:14px">
            <label for="clientName">Client name</label>
            <input id="clientName" type="text" placeholder="Name or initials">

            <div class="row">
              <div style="flex:1">
                <label for="goal">Primary goal</label>
                <select id="goal">
                  <option value="calming">Calming / anxiety support</option>
                  <option value="sleep">Better sleep</option>
                  <option value="focus">Improved focus</option>
                  <option value="mood">Mood lift</option>
                </select>
              </div>
              <div style="width:160px">
                <label for="duration">Duration</label>
                <select id="duration">
                  <option>30 min</option>
                  <option>45 min</option>
                  <option>60 min</option>
                  <option>90 min</option>
                </select>
              </div>
            </div>

            <label for="frequency">Suggested frequency</label>
            <select id="frequency">
              <option>Single session</option>
              <option>Weekly</option>
              <option>Bi-weekly</option>
              <option>Monthly</option>
            </select>

            <label style="margin-top:10px">Notes / contraindications</label>
            <textarea id="notes" rows="3" placeholder="Allergies, pregnancy, pets at home, sensitivities"></textarea>

            <div style="display:flex;gap:8px;margin-top:12px;align-items:center">
              <button id="buildPlan" class="primary">Build plan</button>
              <button id="clearPlan" style="background:#eee;border:0;padding:8px;border-radius:8px;cursor:pointer">Clear</button>
            </div>

            <div style="margin-top:12px">
              <label>Plan summary</label>
              <div id="planSummary" class="summary">No plan yet — click "Build plan".</div>
              <div style="display:flex;gap:8px;margin-top:8px">
                <button id="copyPlan" class="primary">Copy summary</button>
                <button id="downloadPlan" style="background:#fff;border:1px solid #e7e7e7;padding:8px;border-radius:8px;cursor:pointer">Download .txt</button>
              </div>
            </div>
          </div>
        </section>

        <section class="card" style="margin-top:18px">
          <h3>Blend builder — quick, safety-first blend card</h3>
          <p style="color:var(--muted);margin-top:6px">Choose a vibe and a few safety options; the builder will suggest a dilution range and a printable blend card. This is educational, not medical advice.</p>

          <div style="margin-top:12px">
            <label for="vibe">Vibe</label>
            <select id="vibe">
              <option value="calming">Calming</option>
              <option value="uplifting">Uplifting</option>
              <option value="focus">Focus</option>
              <option value="sleep">Sleep-support</option>
            </select>

            <div class="row" style="margin-top:10px">
              <div style="flex:1">
                <label for="carrier">Carrier (per 10ml)</label>
                <select id="carrier">
                  <option value="jojoba">Jojoba</option>
                  <option value="sweet_almond">Sweet almond</option>
                  <option value="fractionated_coconut">Fractionated coconut</option>
                </select>
              </div>
              <div style="width:140px">
                <label for="audience">Client type</label>
                <select id="audience">
                  <option value="adult">Adult (18+)</option>
                  <option value="senior">Older adult</option>
                  <option value="child">Child (6+)</option>
                  <option value="pregnant">Pregnant / postpartum</option>
                </select>
              </div>
            </div>

            <div style="margin-top:10px">
              <label for="notesBlend">Notes (allergies, pets nearby)</label>
              <input id="notesBlend" type="text" placeholder="e.g., cat at home, citrus allergy">
            </div>

            <div style="display:flex;gap:8px;margin-top:12px">
              <button id="makeBlend" class="primary">Create blend</button>
              <button id="clearBlend" style="background:#fff;border:1px solid #e7e7e7;padding:8px;border-radius:8px;cursor:pointer">Reset</button>
            </div>

            <div style="margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
              <div>
                <label>Dilution guidance</label>
                <div id="dilution" class="summary">—</div>
              </div>
              <div>
                <label>Blend card</label>
                <div id="blendCard" class="summary">—</div>
              </div>
            </div>

            <div style="margin-top:8px;display:flex;gap:8px">
              <button id="copyBlend" class="primary">Copy blend card</button>
              <button id="downloadBlend" style="background:#fff;border:1px solid #e7e7e7;padding:8px;border-radius:8px;cursor:pointer">Download .txt</button>
            </div>

          </div>
        </section>

      </div>

      <aside>
        <section class="card">
          <h3>Quick contact</h3>
          <form id="contactForm">
            <label>Name</label>
            <input type="text" name="name" required>
            <label>Email</label>
            <input type="email" name="email" required>
            <label>Message</label>
            <textarea name="message" rows="4" required></textarea>
            <div style="margin-top:10px"><button type="submit" class="primary">Send message</button></div>
            <p style="color:var(--muted);font-size:13px;margin-top:8px">Prefer to call? {{PHONE}} — or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          </form>
        </section>

        <section class="card" style="margin-top:14px">
          <h3>Events series</h3>
          <p style="color:var(--muted)">Our seasonal small-group series is presented as a multi-week learning and practice sequence. Dates and topics updated on the Book page.</p>
          <div style="margin-top:10px"> <a href="book.html" class="primary">View sessions</a></div>
        </section>

        <section class="card" style="margin-top:14px">
          <h3>Location</h3>
          <p style="color:var(--muted);margin:0">{{CITY}}, {{STATE}}</p>
        </section>
      </aside>
    </div>

    <section class="card" style="margin-top:18px">
      <h3>FAQ — Safety & practice notes</h3>
      <div style="margin-top:8px;color:var(--muted);font-size:14px">
        <p><strong>Dilution:</strong> Suggested dilution ranges are general aromatherapy practice notes and not medical instructions. Typical topical dilutions used in our non-medical blends are around 0.5%–3% for most adults for routine use; certain situations call for lower dilutions. The Blend builder gives conservative guidance based on client type.</p>
        <p><strong>Patch test:</strong> Always perform a patch test: apply 1 drop of diluted blend to inner forearm and observe 24 hours. Avoid if irritation occurs.</p>
        <p><strong>Pregnancy & breastfeeding:</strong> Some essentials are commonly avoided or used at lower dilutions during pregnancy. If client is pregnant or breastfeeding, consult their healthcare provider before topical use. We default to lower suggested dilutions for these cases.</p>
        <p><strong>Pets:</strong> Many essential oils can affect pets, especially cats. Avoid applying strong oils directly to pets, and keep diffusers or applied blends away from animal sleeping areas. Consult a veterinarian familiar with essential oils if you are unsure.</p>
        <p><strong>Allergies & medications:</strong> Aromas may interact with sensitivities. We suggest discussing ongoing medications or severe allergies prior to using a blend. Our suggestions are not a substitute for professional medical advice.</p>
      </div>
    </section>

  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;color:var(--muted)">© <span id="year"></span> {{BUSINESS_NAME}} — small group events and private consultations. Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
  </footer>

  <script>
    // set year
    document.getElementById('year').textContent = new Date().getFullYear();

    // Session Planner
    const buildBtn = document.getElementById('buildPlan');
    const clearBtn = document.getElementById('clearPlan');
    const copyBtn = document.getElementById('copyPlan');
    const downloadBtn = document.getElementById('downloadPlan');
    const summaryEl = document.getElementById('planSummary');

    function makePlanText(){
      const name = document.getElementById('clientName').value.trim() || '—';
      const goal = document.getElementById('goal').value;
      const duration = document.getElementById('duration').value;
      const frequency = document.getElementById('frequency').value;
      const notes = document.getElementById('notes').value.trim() || 'None noted.';

      const goalMap = {calming:'Calming support (breath + gentle topical blend)',sleep:'Sleep-support session (wind-down practices)',focus:'Focus-enhancing session (short ritual + inhalation)',mood:'Mood uplift (aroma + movement)'};

      const text = [
        `Client: ${name}`,
        `Goal: ${goalMap[goal] || goal}`,
        `Duration: ${duration}`,
        `Frequency: ${frequency}`,
        `Notes / contraindications: ${notes}`,
        '',
        'Suggested approach: combine a gentle intake, 10–15 minutes of guided practice, and a topical or inhalation blend chosen for the stated goal. Use conservative dilutions and patch testing prior to topical application.'
      ].join('\n');

      return text;
    }

    buildBtn.addEventListener('click', ()=>{
      summaryEl.textContent = makePlanText();
    });

    clearBtn.addEventListener('click', ()=>{
      document.getElementById('clientName').value = '';
      document.getElementById('notes').value = '';
      summaryEl.textContent = 'No plan yet — click "Build plan".';
    });

    copyBtn.addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText(summaryEl.textContent);
        copyBtn.textContent = 'Copied!';
        setTimeout(()=>copyBtn.textContent = '{{PRIMARY_CTA_LABEL}}',1400);
      }catch(e){
        alert('Copy failed — select and copy manually.');
      }
    });

    downloadBtn.addEventListener('click', ()=>{
      const blob = new Blob([summaryEl.textContent],{type:'text/plain'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    });

    // Blend builder
    const makeBlendBtn = document.getElementById('makeBlend');
    const clearBlendBtn = document.getElementById('clearBlend');
    const dilutionEl = document.getElementById('dilution');
    const blendCardEl = document.getElementById('blendCard');
    const copyBlendBtn = document.getElementById('copyBlend');
    const downloadBlendBtn = document.getElementById('downloadBlend');

    const vibeMap = {
      calming:{name:'Calming', oils:['Lavender','Roman Chamomile','Frankincense'] , basePercent:2.0},
      uplifting:{name:'Uplifting', oils:['Sweet Orange (use sun-safe timing)','Grapefruit (caution, phototoxic)','Bergamot (distilled, use low%)'], basePercent:2.0},
      focus:{name:'Focus', oils:['Rosemary (avoid in epilepsy)','Basil','Peppermint (low % for sensitive skin)'], basePercent:1.5},
      sleep:{name:'Sleep-support', oils:['Lavender','Vetiver','Cedarwood'], basePercent:2.5}
    };

    function computeDilution(audience, base){
      // conservative, non-medical guidance
      if(audience === 'adult') return {percent: base.toFixed(1), note:'General guidance for adults.'};
      if(audience === 'senior') return {percent: Math.max(0.8, base*0.75).toFixed(1), note:'Lower dilution suggested for older adults.'};
      if(audience === 'child') return {percent: Math.max(0.3, base*0.25).toFixed(2), note:'Careful, conservative dilution for children. Use only for ages indicated and with consent.'};
      if(audience === 'pregnant') return {percent: Math.max(0.5, base*0.5).toFixed(1), note:'Reduced dilution suggested and consult a healthcare provider if unsure.'};
      return {percent: base.toFixed(1), note:''};
    }

    makeBlendBtn.addEventListener('click', ()=>{
      const vibeKey = document.getElementById('vibe').value;
      const carrier = document.getElementById('carrier').value.replace('_',' ');
      const audience = document.getElementById('audience').value;
      const notes = document.getElementById('notesBlend').value.trim() || 'None.';

      const info = vibeMap[vibeKey];
      const dilution = computeDilution(audience, info.basePercent);

      dilutionEl.textContent = `Suggested dilution: ${dilution.percent}% of essential oil per total topical volume (example: ${dilution.percent}% ≈ ${((parseFloat(dilution.percent)/100)*10).toFixed(2)} ml of essential oil per 10 ml carrier).\nNote: ${dilution.note} Always patch test.`;

      const chosenOils = info.oils.slice(0,3).join(', ');
      const cardText = [
        `${info.name} blend (non-medical, educational)`,
        `Carrier: ${carrier}`,
        `Dilution: ${dilution.percent}%`,
        `Essential oils (suggested): ${chosenOils}`,
        `Notes: ${notes}`,
        '',
        'Usage: Apply 1–2 drops of diluted blend to the inner forearm for a patch test. Diffuse briefly in well-ventilated areas for shared spaces. Keep away from eyes and mucous membranes.'
      ].join('\n');

      blendCardEl.textContent = cardText;
    });

    clearBlendBtn.addEventListener('click', ()=>{
      dilutionEl.textContent = '—';
      blendCardEl.textContent = '—';
      document.getElementById('notesBlend').value = '';
    });

    copyBlendBtn.addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText(blendCardEl.textContent);
        copyBlendBtn.textContent = 'Copied!';
        setTimeout(()=>copyBlendBtn.textContent = 'Copy blend card',1400);
      }catch(e){alert('Copy failed');}
    });

    downloadBlendBtn.addEventListener('click', ()=>{
      const blob = new Blob([blendCardEl.textContent],{type:'text/plain'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = 'blend-card.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
    });

    // contact form stub
    document.getElementById('contactForm').addEventListener('submit', (e)=>{
      e.preventDefault();
      alert('Thanks — your message is queued. We will respond to the email provided.');
      e.target.reset();
    });
  </script>
</body>
</html>"}}
{"path":"README.md","content":"# aromatherapy-MORE-2026-02-17T13-07-13-325Z-002

